/* Shared footer counter. Keep this path because existing static pages load it. */
(function () {
  'use strict';

  function start() {
    var visitors = document.getElementById('busuanzi_value_site_uv');
    var views = document.getElementById('busuanzi_value_site_pv') ||
      document.getElementById('busuanzi_value_page_pv');
    if (!visitors || !views) return;

    var group = visitors.parentElement && visitors.parentElement.parentElement;
    if (!group || !group.closest('.footer')) return;

    function metric(icon, label, value) {
      var item = document.createElement('span');
      item.className = 'site-stat';

      var symbol = document.createElement('i');
      symbol.className = icon;
      symbol.setAttribute('aria-hidden', 'true');

      var name = document.createElement('span');
      name.className = 'site-stat-label';
      name.textContent = label;

      value.className = 'site-stat-value';
      value.textContent = '—';
      item.append(symbol, name, value);
      return item;
    }

    views.id = 'busuanzi_value_site_pv';
    group.className = 'site-stats';
    group.setAttribute('role', 'group');
    group.setAttribute('aria-label', '全站访问统计');
    var status = document.createElement('span');
    status.className = 'site-stats-status';
    status.setAttribute('role', 'status');
    group.replaceChildren(
      metric('ri-user-3-fill', '全站访客', visitors),
      metric('ri-eye-fill', '累计浏览', views),
      status
    );

    function state(kind, message) {
      group.dataset.state = kind;
      status.textContent = message;
    }

    function count(value) {
      if (typeof value !== 'number' && typeof value !== 'string') return null;
      var raw = String(value);
      if (!/^\d+$/.test(raw)) return null;
      var parsed = Number(raw);
      return Number.isSafeInteger(parsed) ? parsed : null;
    }

    if (/^(localhost|127\.0\.0\.1)$/.test(location.hostname)) {
      state('preview', '本地预览不计数');
      return;
    }

    state('loading', '统计加载中…');
    var callback = 'BusuanziCallback_' + Math.floor(1099511627776 * Math.random());
    var script = document.createElement('script');
    var finished = false;
    var timer;

    function finish(kind, message) {
      if (finished) return false;
      finished = true;
      window.clearTimeout(timer);
      script.remove();
      delete window[callback];
      state(kind, message);
      return true;
    }

    window[callback] = function (data) {
      if (finished) return;
      var uniqueVisitors = data ? count(data.site_uv) : null;
      var totalViews = data ? count(data.site_pv) : null;
      if (uniqueVisitors === null || totalViews === null) {
        finish('error', '统计暂不可用');
        return;
      }
      visitors.textContent = uniqueVisitors.toLocaleString('zh-CN');
      views.textContent = totalViews.toLocaleString('zh-CN');
      finish('ready', '');
    };
    script.onerror = function () { finish('error', '统计暂不可用'); };
    script.async = true;
    script.src = 'https://busuanzi.ibruce.info/busuanzi?jsonpCallback=' + callback;
    timer = window.setTimeout(function () { finish('error', '统计暂不可用'); }, 8000);
    document.head.appendChild(script);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
}());
